import re as _re

_TIME = _re.compile(
    r"([0-9]{4})-([0-9]{2})-([0-9]{2})([T ])([0-9]{2}):([0-9]{2}):([0-9]{2})(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})?\Z"
)


def parse_data_time(text, legacy=True):
    """A time of data.md section 2 as an aware datetime; ValueError otherwise.

    With `legacy`, `YYYY-MM-DD HH:MM:SS` (UTC, release 1.2) is accepted too.
    """
    from datetime import timedelta

    if not isinstance(text, str):
        raise ValueError("not text")
    m = _TIME.match(text)
    if not m:
        raise ValueError(text)
    y, mo, d, sep, h, mi, s, frac, off = m.groups()
    if off is None:
        if not legacy or sep != " " or frac:
            raise ValueError(text)
        tz = timezone.utc
    else:
        if sep != "T":
            raise ValueError(text)
        if off == "Z":
            tz = timezone.utc
        else:
            oh, om = int(off[1:3]), int(off[4:6])
            if oh > 23 or om > 59:
                raise ValueError(text)
            delta = timedelta(hours=oh, minutes=om)
            tz = timezone(delta if off[0] == "+" else -delta)
    micro = int((frac[1:] + "000000")[:6]) if frac else 0
    return datetime(int(y), int(mo), int(d), int(h), int(mi), int(s), micro, tzinfo=tz)
