"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta, timezone

from logkeep import streams
from logkeep.errors import DataError

KEYS = ("max_size", "max_age", "naming", "offset", "compress_after", "keep", "keep_days")
BUILTIN = {"max_size": None, "max_age": None, "naming": "numbered", "offset": timezone.utc,
           "compress_after": 1, "keep": 5, "keep_days": None}

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_NUM = re.compile(r"[0-9]+\Z")


def _bad(msg):
    raise DataError("policy", f"policy.ini: {msg}")


def _value(key, v):
    if key == "max_size":
        if v == "off":
            return None
        m = _SIZE.match(v)
        if not m:
            _bad(f"bad size {v!r}")
        return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]
    if key == "max_age":
        if v == "off":
            return None
        m = _DUR.match(v)
        if not m:
            _bad(f"bad duration {v!r}")
        return timedelta(**{{"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]: int(m.group(1))})
    if key == "naming":
        if v not in ("numbered", "dated"):
            _bad(f"bad naming {v!r}")
        return v
    if key == "offset":
        m = _OFF.match(v)
        if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
            _bad(f"bad offset {v!r}")
        d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
        return timezone(d if m.group(1) == "+" else -d)
    if key == "keep_days" and v == "off":
        return None
    if not _NUM.match(v):
        _bad(f"bad number {v!r}")
    n = int(v)
    if key in ("keep", "keep_days") and n < 1:
        _bad(f"{key} must be 1 or more")
    return n


def load(path):
    """Returns (defaults, {stream: settings dict of its own section})."""
    if not path.exists():
        return {}, {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"policy.ini: {e}") from None
    defaults = None
    sections = {}
    cur = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad(f"bad line {line!r}")
            head = line[1:-1]
            if head == "defaults":
                if defaults is not None:
                    _bad("section given twice")
                defaults = cur = {}
            elif head.startswith("stream ") and streams.valid(head[7:]):
                if head[7:] in sections:
                    _bad("section given twice")
                cur = sections[head[7:]] = {}
            else:
                _bad(f"unknown section {head!r}")
            continue
        if cur is None or "=" not in line:
            _bad(f"bad line {line!r}")
        key, _, val = line.partition("=")
        key, val = key.strip(), val.strip()
        if key not in KEYS:
            _bad(f"unknown key {key!r}")
        if key in cur:
            _bad(f"key {key} given twice")
        cur[key] = _value(key, val)
    return defaults or {}, sections


def settings(defaults, sections, name):
    out = dict(BUILTIN)
    out.update(defaults)
    out.update(sections.get(name, {}))
    return out
