"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, timedelta

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_NUM = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z", re.ASCII)


def _check_state(doc, existing):
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        try:
            if "opened" in entry:
                dates.parse_data_time(entry["opened"])
            if "archives" in entry:
                arch = entry["archives"]
                if not isinstance(arch, dict):
                    raise ValueError("archives")
                for v in arch.values():
                    dates.parse_data_time(v)
            if "rotations" in entry:
                r = entry["rotations"]
                if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                    raise ValueError("rotations")
        except ValueError as e:
            raise DataError("state", f"state.json: bad entry for {name}: {e}") from None


def _scan(ctx, name, naming):
    d = streams.logs_dir(ctx.data)
    prefix = f"{name}.log."
    found = []
    seen = set()
    if d.is_dir():
        for p in d.iterdir():
            if not p.is_file() or not p.name.startswith(prefix):
                continue
            rest = p.name[len(prefix):]
            if naming == "numbered":
                m = _NUM.match(rest)
                if not m:
                    continue
                key = (int(m.group(1)),)
                gz = bool(m.group(2))
            else:
                m = _DATED.match(rest)
                if not m:
                    continue
                try:
                    day = date.fromisoformat(m.group(1))
                except ValueError:
                    continue
                key = (day, int(m.group(2) or 1))
                gz = bool(m.group(3))
            if key in seen:
                raise DataError("archives", f"{name}: two archives in the same place")
            seen.add(key)
            found.append({"name": p.name, "gz": gz, "key": key, "new": False})
    return found


def _first_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
        token = line.rstrip(b"\n").split(b" ", 1)[0].decode("utf-8")
        t = dates.parse_data_time(token, legacy=False)
        return t
    except (OSError, UnicodeDecodeError, ValueError):
        return None


def run(ctx, names, dry_run, force):
    data = ctx.data
    defaults, sections = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(data)) | set(sections)
    _check_state(doc, existing)
    if names:
        names = sorted(set(names))
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        names = sorted(existing)

    plans = []
    for name in names:
        st = policy.settings(defaults, sections, name)
        naming = st["naming"]
        arch = _scan(ctx, name, naming)
        plans.append((name, st, arch))

    out = []
    ops = []  # file operations
    new_entries = {}
    n_rot = n_rem = n_comp = 0
    now = ctx.now
    for name, st, arch in plans:
        naming = st["naming"]
        entry = doc["streams"].get(name, {})
        times = entry.get("archives", {})
        log = streams.log_path(data, name)
        has_log = log.is_file()
        size = log.stat().st_size if has_log else 0
        opened = None
        if "opened" in entry:
            opened = dates.parse_data_time(entry["opened"])
        elif has_log:
            opened = _first_time(log)
        if not has_log:
            what, rotated = "no log", False
        elif size == 0:
            what, rotated = "empty", False
        elif force:
            what, rotated = "rotate (forced)", True
        elif st["max_size"] is not None and size >= st["max_size"]:
            what, rotated = "rotate (size)", True
        elif st["max_age"] is not None and opened is not None and now - opened >= st["max_age"]:
            what, rotated = "rotate (age)", True
        else:
            what, rotated = "not due", False

        if naming == "numbered":
            arch.sort(key=lambda a: a["key"])
        else:
            arch.sort(key=lambda a: a["key"], reverse=True)
        for a in arch:
            a["time"] = times.get(a["name"])
            a["old"] = a["name"]
        if rotated:
            if naming == "numbered":
                new = {"name": f"{name}.log.1", "gz": False, "key": (0,)}
            else:
                day = now.astimezone(st["offset"]).date()
                ks = {a["key"][1] for a in arch if a["key"][0] == day}
                if not ks:
                    k = 1
                else:
                    k = 2
                    while k in ks:
                        k += 1
                nm = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
                new = {"name": nm, "gz": False, "key": (day, k)}
            new.update(new=True, time=dates.stamp(now), old=None)
            arch.append(new)
            if naming == "numbered":
                arch.sort(key=lambda a: a["key"])
            else:
                arch.sort(key=lambda a: a["key"], reverse=True)

        keep, keep_days = st["keep"], st["keep_days"]
        remain, removed = [], []
        for i, a in enumerate(arch, 1):
            drop = i > keep
            if not drop and keep_days is not None and a["time"] is not None:
                t = dates.parse_data_time(a["time"])
                if now - t >= timedelta(days=keep_days):
                    drop = True
            (removed if drop else remain).append(a)

        lines = [f"{name}: {what}"]
        comp_here = 0
        for i, a in enumerate(remain, 1):
            base = a["name"][:-3] if a["gz"] else a["name"]
            comp = (not a["gz"]) and i > st["compress_after"]
            if naming == "numbered":
                base = f"{name}.log.{i}"
            final = base + (".gz" if (a["gz"] or comp) else "")
            a["final"], a["comp"] = final, comp
            comp_here += comp
            if a["new"]:
                lines.append(f"  new {final}")
            elif final != a["old"]:
                lines.append(f"  {final} <- {a['old']}")
            else:
                lines.append(f"  {final}")
        for a in removed:
            lines.append(f"  remove {a['name']}")
        out.extend(lines)
        n_rot += rotated
        n_rem += len(removed)
        n_comp += comp_here
        ops.append((name, log, rotated, remain, removed))

        ne = {}
        if rotated:
            ne["opened"] = dates.stamp(now)
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = {a["final"]: a["time"] for a in remain if a["time"] is not None}
        new_entries[name] = ne

    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    logs = streams.logs_dir(data)
    for name, log, rotated, remain, removed in ops:
        writes = []
        deletes = [logs / a["name"] for a in removed if not a["new"]]
        for a in remain:
            if a["new"]:
                content = log.read_bytes()
            elif a["final"] != a["old"] or a["comp"]:
                content = (logs / a["old"]).read_bytes()
                deletes.append(logs / a["old"])
            else:
                continue
            if a["comp"]:
                content = gzip.compress(content, mtime=0)
            writes.append((logs / a["final"], content))
        for p in deletes:
            p.unlink()
        for p, content in writes:
            p.write_bytes(content)
        if rotated:
            log.write_bytes(b"")
    doc["streams"].update(new_entries)
    state.save(ctx.state_path, doc)
    return out
